import traceback

def moyenne(notes):
    return sum(notes) / len(notes)

def bulletin(eleve):
    return eleve["nom"] + " : " + str(moyenne(eleve["notes"]))

try:
    bulletin({"nom": "Afi", "notes": []})
except ZeroDivisionError as e:
    print(type(e).__name__, ":", e)
    print([cadre.name for cadre in traceback.extract_tb(e.__traceback__)])

stock = {"riz": 40, "huile": 12}
for erreur in [lambda: stock["sucre"], lambda: [1, 2][5], lambda: "Total : " + 5, lambda: int("douze")]:
    try:
        erreur()
    except Exception as e:
        print(type(e).__name__)

